contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public {
        require(newOwner != address(0));

        c.transferOwnership(newOwner);
        address ownerAfter = c.owner();

        bool revertedFromOld = false;
        try c.transferOwnership(address(0xdead)) {
            revertedFromOld = false;
        } catch {
            revertedFromOld = true;
        }

        bool revertedFromNew = false;
        try c.transferOwnership(newOwner) {
            revertedFromNew = false;
        } catch {
            revertedFromNew = true;
        }

        assert(ownerAfter == newOwner && revertedFromOld && !revertedFromNew);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner, address attacker) public payable {
        address beforeOwner = c.owner();
        bool unauthorizedRevertedBefore;
        try c.transferOwnership(attacker) {
            unauthorizedRevertedBefore = false;
        } catch {
            unauthorizedRevertedBefore = true;
        }
        bool successfulTransfer;
        try c.transferOwnership(newOwner) {
            successfulTransfer = true;
        } catch {
            successfulTransfer = false;
        }
        address afterOwner = c.owner();
        bool oldOwnerStillOwner = (afterOwner == beforeOwner);
        if (successfulTransfer) {
            assert(afterOwner == newOwner && newOwner != beforeOwner && oldOwnerStillOwner == false);
        } else {
            assert(afterOwner == beforeOwner);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public payable {
        address beforeOwner = c.owner();
        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }
        address afterOwner = c.owner();
        assert(reverted ? afterOwner == beforeOwner : afterOwner == newOwner);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOwner) public payable {
        require(caller != address(0));
        require(newOwner != address(0));
        require(caller != newOwner);

        address beforeOwner = c.owner();
        require(msg.sender == beforeOwner);

        bool success;
        try c.transferOwnership(newOwner) {
            success = true;
        } catch {
            success = false;
        }

        address afterOwner = c.owner();

        assert(success == (caller == beforeOwner) && (success ? afterOwner == newOwner : afterOwner == beforeOwner));
    }

    receive() external payable {}
}

